@prefix ada: <https://ada.astromat.org/metadata/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a ada:QRISCalibrated ;
                    ada:calibrationFile "calibration_neon_20240301.csv" ;
                    ada:exposureTime 10 ;
                    ada:focalLength 300 ;
                    ada:illuminationColor "532nm green" ;
                    ada:illuminationLevel 50 ;
                    ada:pipelineVersion "2.1.0" ;
                    ada:target "olivine grain" ] ;
            sh:resultMessage "QRIS detail nodes must declare ada:componentType." ;
            sh:resultPath ada:componentType ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:maxCount 1 ;
                    sh:message "QRIS detail nodes must declare ada:componentType." ;
                    sh:minCount 1 ;
                    sh:path ada:componentType ] ] .
